const teams={VGK:{name:'Vegas Golden Knights',city:'Las Vegas',arena:'T-Mobile Arena',lat:36.1,lon:-115.18},NJD:{name:'New Jersey Devils',city:'Newark',arena:'Prudential Center',lat:40.73,lon:-74.17},FLA:{name:'Florida Panthers',city:'Sunrise',arena:'Amerant Bank Arena',lat:26.16,lon:-80.33},WPG:{name:'Winnipeg Jets',city:'Winnipeg',arena:'Canada Life Centre',lat:49.89,lon:-97.14},CGY:{name:'Calgary Flames',city:'Calgary',arena:'Scotiabank Saddledome',lat:51.04,lon:-114.05},SEA:{name:'Seattle Kraken',city:'Seattle',arena:'Climate Pledge Arena',lat:47.62,lon:-122.35}};
const qs=new URLSearchParams(location.search),a=qs.get('a')||'VGK',b=qs.get('b')||'NJD',root=document.querySelector('#nhl-content');
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const point=t=>({x:93+(t.lon+130)*6.15,y:61+(60-t.lat)*7.55});
async function load(){try{const data=await fetch('nhl-data.json').then(r=>r.json());render(data.standings[a],data.standings[b],data.meetings[`${a}-${b}`]||[])}catch{root.innerHTML='<div class="nhl-error"><h1>Kunde inte hämta NHL-data</h1><p>Försök igen om en liten stund.</p><a href="index.html">Tillbaka till sportguiden</a></div>'}}
function mapSvg(pa,pb){return `<svg class="na-map realistic" viewBox="0 0 700 470" role="img" aria-label="Geografisk karta över Nordamerika"><defs><linearGradient id="land" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#d7f5d6"/><stop offset="1" stop-color="#8fcba5"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="7" stdDeviation="7" flood-opacity=".18"/></filter></defs><g filter="url(#shadow)"><path class="land canada" d="M72 70L105 48 144 52 168 31 207 48 239 35 271 54 304 40 333 60 367 45 402 67 438 58 472 75 508 72 532 95 574 108 602 142 592 174 568 192 548 215 515 217 498 202 470 211 450 196 424 205 397 190 372 205 345 193 318 205 291 188 264 201 237 186 211 197 184 178 156 182 135 160 105 158 91 130 65 112Z"/><path class="land usa" d="M122 181L153 180 184 194 216 188 245 202 278 195 309 209 340 199 370 211 400 200 430 210 459 199 486 218 512 218 528 238 512 259 490 268 474 292 445 303 415 320 383 323 350 315 319 321 286 310 253 314 225 299 196 291 173 268 151 251 139 224 120 208Z"/><path class="land mexico" d="M174 269L199 292 229 302 256 318 285 327 309 351 328 375 353 390 371 416 356 437 333 421 318 394 296 380 276 356 250 348 228 326 201 319 181 299Z"/><path class="land alaska" d="M36 72L60 46 99 38 119 51 97 70 70 76 52 94 31 91Z"/><path class="land greenland" d="M512 27L554 17 589 39 598 71 576 95 544 86 522 59Z"/></g><path class="border" d="M122 181L184 194 245 202 309 209 370 211 430 210 486 218 512 218"/><g class="lakes"><path d="M415 205q18-19 37-3-9 22-30 25Z"/><path d="M447 226q20-12 32 1-11 15-30 14Z"/><path d="M476 238q14-9 24 2-10 12-22 9Z"/><path d="M431 230q11-8 18 2-7 10-17 8Z"/></g><text class="country" x="305" y="145">KANADA</text><text class="country" x="315" y="275">USA</text><text class="country" x="267" y="355">MEXIKO</text><path class="route" d="M${pa.x} ${pa.y} Q350 90 ${pb.x} ${pb.y}"/><g class="pin" transform="translate(${pa.x} ${pa.y})"><circle r="14"/><circle r="5"/><text y="-23">${a}</text></g><g class="pin two" transform="translate(${pb.x} ${pb.y})"><circle r="14"/><circle r="5"/><text y="-23">${b}</text></g></svg>`}
function render(sa,sb,games){const ta=teams[a],tb=teams[b],pa=point(ta),pb=point(tb);root.innerHTML=`<section class="match-hero"><p class="eyebrow">NHL · MATCHFAKTA</p><div class="matchup"><div class="club"><img src="https://assets.nhle.com/logos/nhl/svg/${a}_light.svg" alt=""><h1>${esc(ta.name)}</h1><p>${esc(ta.city)}</p></div><div class="versus"><span>MOT</span><i></i></div><div class="club"><img src="https://assets.nhle.com/logos/nhl/svg/${b}_light.svg" alt=""><h1>${esc(tb.name)}</h1><p>${esc(tb.city)}</p></div></div><p class="data-note"><span class="pulse"></span> Uppdaterat från NHL:s officiella data</p></section><section class="nhl-grid"><article class="nhl-card"><p class="eyebrow dark">TABELLEN JUST NU</p><h2>Ligaplacering</h2>${standRow(a,ta,sa)}${standRow(b,tb,sb)}<a href="https://www.nhl.com/standings/" target="_blank">Se hela NHL-tabellen ↗</a></article><article class="nhl-card"><p class="eyebrow dark">SENASTE MÖTENA</p><h2>Inbördes matcher</h2>${games.length?games.map(gameRow).join(''):'<p>Inga avslutade möten hittades.</p>'}<small>Nyaste matchen först.</small></article></section><section class="map-section"><div><p class="eyebrow">VAR LAGEN FINNS</p><h2>Två lag.<br>En kontinent.</h2><div class="map-legend"><p><b>${esc(ta.city)}</b><span>${esc(ta.arena)}</span></p><p><b>${esc(tb.city)}</b><span>${esc(tb.arena)}</span></p></div></div>${mapSvg(pa,pb)}</section>`}
function standRow(code,t,s){return `<div class="stand-row"><img src="https://assets.nhle.com/logos/nhl/svg/${code}_light.svg" alt=""><div><b>${esc(t.name)}</b><span>${s?`${s.wins}–${s.losses}–${s.otLosses} · ${s.points} poäng`:'Uppgift saknas'}</span></div><strong>${s?`#${s.leagueSequence}`:'–'}</strong></div>`}function gameRow(g){const x=g.awayTeam,y=g.homeTeam;return `<div class="meeting-row"><time>${new Date(g.gameDate+'T12:00:00').toLocaleDateString('sv-SE',{day:'numeric',month:'short',year:'numeric'})}</time><div><span>${esc(x.placeName||x.abbrev)}</span><b>${x.score} – ${y.score}</b><span>${esc(y.placeName||y.abbrev)}</span></div><small>${esc(g.venue||'')}</small></div>`}load();
